alpha.capabilities.query:
query AlphaCapabilities($context: ContextInput!) {
  capabilities(context: $context) {
    version
    wssUrl
    features
  }
}

alpha.resolveRequest.query:
query AlphaResolveRequest($context: ContextInput!, $input: ResolveInput!) {
  resolveRequest(context: $context, input: $input) {
    requestId
    committed
    sequence
  }
}

alpha.items.query:
query AlphaItems($context: ContextInput!, $input: ItemsInput!) {
  items(context: $context, input: $input) {
    items {
      id
      name
      fruit
      weight
      ripe
      oldName
      legacyCode
      grid
      aliases
      history
    }
    complete
    refreshRequired
    nextCursor
  }
}

alpha.events.query:
query AlphaEvents($context: ContextInput!, $input: EventsInput!) {
  events(context: $context, input: $input) {
    items {
      sequence
      type
      subjectRef {
        kind
        id
      }
      payload {
        itemId
        jobId
        revision
        note
      }
    }
    complete
    refreshRequired
    nextCursor
  }
}

alpha.job.query:
query AlphaJob($context: ContextInput!, $input: JobInput!) {
  job(context: $context, input: $input) {
    operationId
    state
    progress
    output
  }
}

alpha.fetchHTTPStatus.query:
query AlphaFetchHTTPStatus($context: ContextInput!, $input: FetchInput) {
  fetchHTTPStatus(context: $context, input: $input)
}

alpha.startJob.query:
mutation AlphaStartJob($context: ContextInput!, $input: StartJobInput!) {
  startJob(context: $context, input: $input) {
    requestId
    receipt {
      requestId
      committed
      sequence
    }
    job {
      operationId
      state
    }
  }
}

alpha.ping.query:
mutation AlphaPing($context: ContextInput!, $input: PingInput) {
